### 3.2 Warp特化三角色流水线内核

```cuda
// ============================================================
// Warp特化三角色流水线内核
// 三个warp分别承担不同角色：
//   warp_id == 0: 加载器（Loader）—— 从全局内存异步加载A和B的数据块
//   warp_id == 1: 计算器（Compute）—— 执行矩阵乘法计算
//   warp_id == 2: 存储器（Storer）—— 将计算结果写回全局内存
// ============================================================
#include <cuda/pipeline>
#include <cooperative_groups.h>
namespace cg = cooperative_groups;

// 数据块尺寸：112×112
// 共享内存需求：3 × 112 × 112 × 4字节 = 150,528字节 < 227,328字节（Blackwell每块限制）
#define TILE_SIZE 112

// -----------------------------------------------------------
// 设备函数：计算完整数据块的矩阵乘法 C = A × B
// 每个线程（按lane_id步进）计算多个输出元素
// -----------------------------------------------------------
__device__ void compute_full_tile(const float* __restrict__ A_tile,
                                  const float* __restrict__ B_tile,
                                  float* __restrict__ C_tile,
                                  int lane_id) {
    // 每个线程以warpSize为步长遍历所有输出元素
    for (int idx = lane_id; idx < TILE_SIZE * TILE_SIZE; idx += warpSize) {
        int row = idx / TILE_SIZE;
        int col = idx % TILE_SIZE;
        float acc = 0.0f;
        // 计算点积
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            acc += A_tile[row * TILE_SIZE + k] * B_tile[k * TILE_SIZE + col];
        }
        C_tile[idx] = acc;
    }
}

// -----------------------------------------------------------
// 主内核：Warp特化三角色流水线
// 作为持久内核运行，通过全局warp索引循环处理多个数据块
// -----------------------------------------------------------
extern "C"
__global__ void warp_specialized_pipeline_kernel(
        const float* __restrict__ A_global,
        const float* __restrict__ B_global,
        float* __restrict__ C_global,
        int numTiles) {
    thread_block cta = this_thread_block();

    // 三个方阵数据块在动态共享内存中：A、B、C
    extern __shared__ float shared_mem[];
    float* A_tile = shared_mem;
    float* B_tile = A_tile + TILE_SIZE * TILE_SIZE;
    float* C_tile = B_tile + TILE_SIZE * TILE_SIZE;

    // 三阶段流水线共享状态（块级作用域）
    __shared__ cuda::pipeline_shared_state<cuda::thread_scope_block, 3>
        pipe_state;
    auto pipe = cuda::make_pipeline(cta, &pipe_state);

    int warp_id  = threadIdx.x >> 5;   // 当前线程所属warp的ID
    int lane_id  = threadIdx.x & 31;    // 当前线程在warp内的lane ID
    int warps_per_block = blockDim.x >> 5;  // 每个块的warp数量

    // 网格级warp索引，用于持久分块调度
    int totalWarps = gridDim.x * warps_per_block;
    int global_warp = warp_id + blockIdx.x * warps_per_block;

    // 持久内核循环：每个warp按步长totalWarps遍历所有数据块
    for (int tile = global_warp; tile < numTiles; tile += totalWarps) {
        size_t offset = static_cast<size_t>(tile) * TILE_SIZE * TILE_SIZE;

        // ===== 角色一：加载器warp（warp_id == 0）=====
        if (warp_id == 0) {
            // 生产者获取：保留流水线阶段
            pipe.producer_acquire();

            // 异步拷贝A和B的数据块到共享内存
            auto bytes = TILE_SIZE * TILE_SIZE * sizeof(float);
            cuda::memcpy_async(cta, A_tile, A_global + offset,
                               cuda::aligned_size_t<32>{bytes}, pipe);
            cuda::memcpy_async(cta, B_tile, B_global + offset,
                               cuda::aligned_size_t<32>{bytes}, pipe);

            // 生产者提交：通知计算warp数据已就绪
            pipe.producer_commit();
        }

        // ===== 角色二：计算warp（warp_id == 1）=====
        if (warp_id == 1) {
            // 消费者等待：等待A_tile和B_tile加载完成
            pipe.consumer_wait();

            // 从A_tile和B_tile计算C_tile
            compute_full_tile(A_tile, B_tile, C_tile, lane_id);

            // 消费者释放：释放A/B阶段，允许加载器重用
            pipe.consumer_release();

            // 计算warp现在变为生产者：发布C_tile给存储器warp
            pipe.producer_acquire();
            pipe.producer_commit();
        }

        // ===== 角色三：存储器warp（warp_id == 2）=====
        if (warp_id == 2) {
            // 消费者等待：等待C_tile计算完成
            pipe.consumer_wait();

            // 将C_tile写回全局内存（warp条带化循环）
            for (int idx=lane_id; idx<TILE_SIZE*TILE_SIZE; idx+=warpSize) {
                C_global[offset + idx] = C_tile[idx];
            }

            // 消费者释放：释放C阶段
            pipe.consumer_release();
        }
    }
    // 启动时动态共享内存大小 = 3 * TILE_SIZE * TILE_SIZE * sizeof(float)
    // 当动态共享内存 > 48KB时，需要设置
    // cudaFuncAttributeMaxDynamicSharedMemorySize
}
```

### 3.3 CTA集群与DSMEM使用示例

```cuda
// ============================================================
// CTA集群内核示例 —— 使用DSMEM进行块间数据共享
// 演示：多个线程块通过DSMEM将本地值求和到块0的共享内存
// ============================================================
#include <cuda_runtime.h>
#include <cooperative_groups.h>
namespace cg = cooperative_groups;

__global__ void MyClusterKernel(/* args */) {
    // 1. 获取当前集群的协作组句柄
    cg::cluster_group cluster = cg::this_cluster();

    // 2. 每个块声明相同大小的extern共享内存缓冲区
    //    DSMEM硬件将逻辑上组合每个块的共享内存为一个虚拟地址空间
    extern __shared__ int shared_buffer[];

    // 3. 获取当前块在集群中的排名和集群大小
    int clusterRank = cluster.block_rank();   // 当前块的排名（0, 1, 2, ...）
    int clusterSize = cluster.num_blocks();    // 集群中块的总数

    // 4. 每个块初始化自己的共享内存部分（简单的本地求和）
    int localSum = threadIdx.x;
    shared_buffer[threadIdx.x] = localSum;

    // 5. 集群级屏障：所有块必须到达此点后才能继续
    //    确保每个块都已写入自己的shared_buffer
    cluster.sync();

    // 6. 获取指向块0（rank 0）共享内存的指针
    //    map_shared_rank返回的指针指向远程CTA的共享内存
    //    支持远程原子操作和内存操作
    //    注意：必须配合cluster.sync()使用以确保数据可见性
    int* remote_buffer = cluster.map_shared_rank(shared_buffer, 0);

    // 7. 非零排名的块将自己的值原子加到块0的缓冲区
    //    atomicAdd通过DSMEM片上网络路由，不经过DRAM
    if (clusterRank != 0) {
        atomicAdd(&remote_buffer[0], shared_buffer[0]);
    }

    // 8. 第二次集群屏障：确保所有原子加操作已完成
    cluster.sync();

    // 9. 块0（rank 0，线程0）读取合并后的结果
    if (clusterRank == 0 && threadIdx.x == 0) {
        printf("Combined sum in cluster[0]: %d\n", shared_buffer[0]);
    }
}
```

